class Order:
    def __init__(self):
        self.items = []
        self.quantities = []
        self.prices = []

class OrderManager:
    def __init__(self, order: Order):
        self.order = order
        self.status = 'open'

    def set_status(self, status: str) -> None:
        self.status = status

class PaymentProcessor:
    def verify_security_code(self, security_code: str) -> bool:
        print("Verifying security code")
        return True  # Assume verification logic

    def pay(self, order_manager: OrderManager, security_code: str):
        if self.verify_security_code(security_code):
            print("Processing payment")
            order_manager.set_status("paid")
        else:
            print("Invalid security code")
